contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint callerBalBefore = address(this).balance;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;

        bool reverted = true;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {} else { reverted = false; }

        uint callerBalAfter = address(this).balance;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;

        assert(reverted ? (callerBalBefore - callerBalAfter <= amount && potAfter == potBefore) : (callerBalBefore - callerBalAfter + 10 <= amount + 10));
    }

    receive() external payable {}
}

